\label{def:LN_domains}
A sequence $\{\Omega_N\}_{N\geqslant1}$ of bounded open sets with $\rho_0|\Omega_N|=N$ for every integer $N\geqslant1$ is \emph{LN-admissible} if
\begin{enumerate}
\item[(A)] (Van Hove) $\big|\{x:\ d(x,\partial\Omega_N)\leqslant h\}\big|=o(|\Omega_N|)$ for every $h>0$;
\item[(B)] (ball condition) $|\Omega_N|\geqslant\delta\,|B(\Omega_N)|$ for some $\delta>0$ independent of $N$, where $B(\Omega_N)$ is the smallest ball containing $\Omega_N$;
\item[(i)] $\sup_N|\Sigma^{+1}_{N,h}|/|\Sigma^{+2}_{N,h}|<\infty$ for every $h>0$;
\item[(ii)] the potential $\varphi_{N,h}(x):=\int_{\mathbb{R}^3}\sigma^+_{N,h}(y)|x-y|^{-1}\,\mathrm dy$ is $o(1)$
as $h\to0$, uniformly in $N\geqslant1$ and $x\in\Omega_N\cup\Sigma^{+1}_{N,h}\cup\Sigma^{+2}_{N,h}$;
\item[(iii)] $D(\sigma^+_{N,h})=o(|\Omega_N|)$ for every $h>0$;
\item[(iv)] for every $h>0$, $|\Sigma^{-2}_{N,h}|>0$ for all sufficiently large $N$, and $D(\sigma^-_{N,h})=o(|\Omega_N|)$ as $N\to\infty$.
\end{enumerate}

\label{thm:LN_stability}
Let $\rho_0>0$ and let $\Omega\subset\mathbb{R}^3$ be a bounded measurable set.
\begin{enumerate}[(i)]
\item (Classical bound) For every $N\geqslant1$ and every $X\in(\mathbb{R}^3)^N$,
\begin{equation}\label{eq:LN_Onsager}
U^{\rho_0}_\Omega(X)\geqslant-\frac{9}{10}\,\frac{N}{r_s}=-\frac{9}{10}\Big(\frac{4\pi}{3}\Big)^{1/3}\rho_0^{1/3}N,\qquad r_s=\Big(\frac{3}{4\pi\rho_0}\Big)^{1/3}.
\end{equation}
In particular, if $N=\rho_0|\Omega|$, then $E^\hbar_\mathrm{Jel}(\rho_0,\Omega)\geqslant E^0_\mathrm{Jel}(\rho_0,\Omega)\geqslant-c_{\rm LN}\,\rho_0^{4/3}|\Omega|$, where
\[
c_{\rm LN}:=\frac35\Big(\frac{9\pi}{2}\Big)^{1/3}=\frac{9}{10}\Big(\frac{4\pi}{3}\Big)^{1/3}\simeq1.4508.
\]
\item (Quantum bound) If $\Omega$ is open and $N=\rho_0|\Omega|$, then
\begin{equation}\label{eq:LN_quantum_stability}
E^\hbar_\mathrm{Jel}(\rho_0,\Omega)\geqslant\big(\hbar^2c_\mathrm{TF}\,\rho_0^{5/3}-c_{\rm LN}\,\rho_0^{4/3}\big)|\Omega|.
\end{equation}
\end{enumerate}

\label{thm:UEG}
Let $\rho_0>0$ and $\hbar>0$.
\begin{enumerate}
\item[(i)]  Let $\{\Omega_N\}$ be bounded connected domains with $|\Omega_N|\to\infty$ which have an $\eta$-regular boundary in the sense of Fisher~\cite{fisher1964free}, for a fixed $\eta$:
\[
\big|\{x:\ d(x,\partial\Omega_N)\leqslant|\Omega_N|^{1/3}t\}\big|\leqslant|\Omega_N|\,\eta(t),\qquad0\leqslant t\leqslant t_0,
\]
with $\eta$ continuous and $\eta(0)=0$. Let $\ell_N\to\infty$ with $\ell_N/|\Omega_N|^{1/3}\to0$, and
\begin{align*}
&\Omega_N^-:=\{x\in\Omega_N:\ d(x,\partial\Omega_N)\geqslant\ell_N\},\\
&\Omega_N^+:=\Omega_N\cup\{x:\ d(x,\partial\Omega_N)\leqslant\ell_N\}.
\end{align*}
Then the limit
\begin{equation}\label{eq:UEG_LLS18}
\boxed{e^\hbar_\mathrm{UEG}(\rho_0):=\lim_{N\to\infty}\ \inf_{\substack{\sqrt\rho\in H^1(\mathbb{R}^3)\\ \rho_0\mathbb{1}_{\Omega_N^-}\leqslant\rho\leqslant\rho_0\mathbb{1}_{\Omega_N^+}}}\frac{E^\hbar(\rho)}{|\Omega_N|}}
\end{equation}
exists and is independent of $\{\Omega_N\}$ and $\{\ell_N\}$.
\item[(ii)] Let $\{\Omega_N\}$ be bounded connected domains with $|\Omega_N|\to\infty$ and
\[
|\partial\Omega_N+B_r|\leqslant Cr|\Omega_N|^{2/3}\qquad\text{for all }0<r\leqslant|\Omega_N|^{1/3}/C,
\]
for some $C>0$. Let $\delta_N>0$ with $\delta_N/|\Omega_N|^{1/3}\to0$ and $\delta_N|\Omega_N|^{1/3}\to\infty$. Then
\begin{equation}\label{eq:UEG_LDA}
\boxed{e^\hbar_\mathrm{UEG}(\rho_0)=\lim_{N\to\infty}e^\hbar_\mathrm{UEG}(\rho_0,\Omega_N,\chi_{\delta_N}),}
\end{equation}
and the limit is independent of $\{\Omega_N\}$, $\{\delta_N\}$ and $\chi$.
\item[(iii)] (Scaling) $e^\hbar_\mathrm{UEG}(\rho_0)=\rho_0^{4/3}\,\tilde e_\mathrm{UEG}\big(\hbar^2\rho_0^{1/3}\big)$, where $\tilde e_\mathrm{UEG}(\lambda):=e^{\sqrt\lambda}_\mathrm{UEG}(1)$, $\lambda>0$, is the energy at unit density.
\item[(iv)] (Regularity) $\lambda\mapsto \tilde e_\mathrm{UEG}(\lambda)$ is concave and non-decreasing on $(0,\infty)$, hence continuous. Therefore $\rho_0\mapsto e^\hbar_\mathrm{UEG}(\rho_0)$ is continuous on $(0,\infty)$.
\item[(v)] (Classical limit) $\lim_{\lambda\to0}\tilde e_\mathrm{UEG}(\lambda)=e_\mathrm{UEG}$, the classical UEG energy of~\cite[Thm.~2.6]{lewin2018statistical}.
\item[(vi)] (High-density limit) $\tilde e_\mathrm{UEG}(\lambda)=c_\mathrm{TF}\lambda-c_{\mathrm{D}}+o(1)$ as $\lambda\to\infty$.
\end{enumerate}

\label{thm:main}
For every integer spin multiplicity $q\geqslant1$, every $\rho_0>0$ and every $\hbar>0$,
\begin{equation}\label{eq:main}
e^\hbar_\mathrm{Jel}(\rho_0)=e^\hbar_\mathrm{UEG}(\rho_0).
\end{equation}
Equivalently, $\tilde e_\mathrm{Jel}(\lambda)=\tilde e_\mathrm{UEG}(\lambda)$ for all $\lambda>0$.

\label{lem:basic_onsager}
Let $\rho\in L^1(\mathbb{R}^3)$ satisfy $0\leqslant\rho\leqslant\bar\rho$, and let $x_1,\dots,x_N\in\mathbb{R}^3$. For $a>0$, let $\mu_j:=|B_a|^{-1}\mathbb{1}_{B_a(x_j)}$. Then
\begin{multline*}
\sum_{1\leqslant j<k\leqslant N}\frac1{|x_j-x_k|}-\sum_{j=1}^N\int_{\mathbb{R}^3}\frac{\rho(y)}{|x_j-y|}\,\mathrm dy+D(\rho)\\
\geqslant D\Big(\sum_{j=1}^N\mu_j-\rho\Big)-N\Big(\frac3{5a}+\frac{2\pi}5\bar\rho a^2\Big).
\end{multline*}
In particular, the left side is at least $-N\big(\frac3{5a}+\frac{2\pi}5\bar\rho a^2\big)$.

\label{lem:basic_product}
Let the states ${\bm{\Gamma}}_1,\ldots,{\bm{\Gamma}}_J$ be number-conserving, fermionic and disjointly supported, with ${\bm{\Gamma}}_j$ supported in $A_j$, finite mean particle number and finite kinetic and interaction energies after extension to $\mathbb{R}^3$. Then ${\bm{\Gamma}}={\bm{\Gamma}}_1\wedge\cdots\wedge{\bm{\Gamma}}_J$ is a number-conserving fermionic state and
\begin{align}
\rho_{{\bm{\Gamma}}}&=\sum_{1\leqslant j\leqslant J}\rho_{{\bm{\Gamma}}_j},\label{eq:basic_product_density}\\
\mathcal{T}({\bm{\Gamma}})&=\sum_{1\leqslant j\leqslant J}\mathcal{T}({\bm{\Gamma}}_j),\label{eq:basic_product_kinetic}\\
\mathcal{C}({\bm{\Gamma}})&=\sum_{1\leqslant j\leqslant J}\mathcal{C}({\bm{\Gamma}}_j)+2\sum_{1\leqslant j<k\leqslant J}D(\rho_{{\bm{\Gamma}}_j},\rho_{{\bm{\Gamma}}_k}).
\label{eq:basic_product_interaction}
\end{align}

\label{thm:basic_fluid}
Let $\rho\geqslant0$ be such that $\sqrt\rho\in H^1(\mathbb{R}^3)$, and let $0<\varepsilon\leqslant1$. There is a number-conserving grand-canonical quasi-free fermionic state ${\bm{\Gamma}}$ with $\rho_{\bm{\Gamma}}=\rho$ such that
\begin{equation}\label{eq:basic_fluid_bound}
\mathcal{E}({\bm{\Gamma}})\leqslant\mathcal{T}({\bm{\Gamma}})
\leqslant\Big(1+\frac\varepsilon{15}\Big)c_\mathrm{TF}\int_{\mathbb{R}^3}\rho^{5/3}
+\frac{19}{\varepsilon}
\int_{\mathbb{R}^3}|\nabla\sqrt\rho|^2.
\end{equation}

\label{thm:basic_localization}
There is a constant $C>0$ such that for every $\rho\geqslant0$ with $\sqrt\rho\in H^1(\mathbb{R}^3)$, every $\delta>0$ and every $h>C\delta$,
\begin{multline}\label{eq:basic_localization}
E(\rho)\geqslant
\left(1-\frac{C\delta}h\right)
\int_{\mathrm{SO}(3)}\frac1{h^3}\int_{C_h}
\sum_{z\in\mathbb{Z}^3}\sum_{j=1}^{24}
E\big((\mathbb{1}_{Q^{-1}(h\mu_j\mathbb{\Delta}+h z+a)}*\eta_\delta)\rho\big)
\,\mathrm da\,\mathrm dQ
\\
-\frac{C}{h}\int_{\mathbb{R}^3}(\rho+\delta^3\rho^2)
-\frac{C}{h\delta}\int_{\mathbb{R}^3}\rho.
\end{multline}

All constants in this proof are independent of $\ell$, of $\delta\in(0,1]$, and of the translation and rotation of the tiling. Dependence on $\Lambda$ and $\rho_0$ is indicated where it enters.

We use the tiling and the partition~\eqref{eq:basic_partition} introduced before Theorem~\ref{thm:basic_localization}. By Lemma~\ref{lem:basic_elementary}(i), every localized density $(\mathbb{1}_{Q^{-1}(h\mu_j\mathbb{\Delta}+h z+a)}*\eta_\delta)\rho_\ell$ is admissible for $E$. Fix $\delta\in(0,1]$ and $h>C\delta$, where $C$ is the constant of Theorem~\ref{thm:basic_localization}, so that $1-C\delta/h>0$. Since $\sqrt{\rho_\ell}\in H^1(\mathbb{R}^3)$, Theorem~\ref{thm:basic_localization} gives
\begin{multline}\label{eq:upper_layer_localization}
E(\rho_\ell)\geqslant
\left(1-\frac{C\delta}h\right)
\int_{\mathrm{SO}(3)}\frac1{h^3}\int_{C_h}
\sum_{z\in\mathbb{Z}^3}\sum_{j=1}^{24}
E\big((\mathbb{1}_{Q^{-1}(h\mu_j\mathbb{\Delta}+h z+a)}*\eta_\delta)\rho_\ell\big)
\,\mathrm da\,\mathrm dQ
\\
-\frac{C}{h}\int_{\mathbb{R}^3}(\rho_\ell+\delta^3\rho_\ell^2)
-\frac{C}{h\delta}\int_{\mathbb{R}^3}\rho_\ell.
\end{multline}

Put
\[
h'=\delta'+d_0h+2\delta+1.
\]
Since $\delta'=o(\ell)$, for all sufficiently large $\ell$ we have $h'<\ell/4$. Comparing the cubes with side lengths $\ell+2h'$ and $\ell-2h'$ yields
\begin{equation}\label{eq:upper_boundary_volume}
|\partial C_\ell+B_{h'}|\leqslant C \ell^2h'.
\end{equation}
For the same $\ell$, the set $C_\ell+B_{\delta'}$ lies in the cube $C_{\ell+2h'}$, whose volume is at most $C\ell^3$. The support and pointwise bounds on $\rho_\ell$ therefore control the integral terms in~\eqref{eq:upper_layer_localization}:
\begin{equation}\label{eq:upper_layer_integrals}
\int_{\mathbb{R}^3}\rho_\ell\leqslant C\Lambda\rho_0\ell^3,
\qquad
\int_{\mathbb{R}^3}(\rho_\ell+\delta^3\rho_\ell^2)
\leqslant C(\Lambda\rho_0+\delta^3\Lambda^2\rho_0^2)\ell^3.
\end{equation}

To treat the first term of \eqref{eq:upper_layer_localization}, we introduce the index set of tetrahedra that meet the enlarged cube $C_\ell+B_{\delta'+\delta}$,
\[
J=\big\{(z,j)\in\mathbb{Z}^3\times\{1,\dots,24\}:Q^{-1}(h\mu_j\mathbb{\Delta}+h z+a)\cap(C_\ell+B_{\delta'+\delta})\ne\emptyset\big\}
\]
 If $(z,j)\notin J$, the localized density $(\mathbb{1}_{Q^{-1}(h\mu_j\mathbb{\Delta}+h z+a)}*\eta_\delta)\rho_\ell$ vanishes,
 because the smeared indicator of the tetrahedron is supported in its $\delta$-enlargement and $\rho_\ell$ vanishes outside
 $C_\ell+B_{\delta'}$. Let further
\[
J_0=\big\{(z,j)\in\mathbb{Z}^3\times\{1,\dots,24\}: Q^{-1}(h\mu_j\mathbb{\Delta}+h z+a)\subset C_\ell\setminus(\partial C_\ell+B_{\delta'+\delta})\big\}
\]
be the set of interior pairs. Clearly $J_0\subset J$. Both sets depend on $\ell$, $Q$ and $a$; see Figure~\ref{fig:bounded_layer}.

