The corresponding tetrahedra are disjoint subsets of $C_\ell$, so
$|J_0|\,|h\mathbb{\Delta}|\leqslant \ell^3$.
Conversely, if a point $x\in C_\ell$ is at a distance more than $h'$ from $\partial C_\ell$, then the index of the tetrahedron containing $x$ belongs to $J_0$. Indeed, every point of that tetrahedron lies within $d_0h$ of $x$. The union of the tetrahedra with indices in $J_0$ consequently contains $C_{\ell-2h'}$ up to null sets. Thus
\begin{equation}\label{eq:upper_interior_count}
0\leqslant \ell^3-|J_0|\,|h\mathbb{\Delta}|
\leqslant \ell^3-(\ell-2h')^3
\leqslant C \ell^2h'.
\end{equation}
For $(z,j)\in J_0$, the $\delta$-enlargement of the tetrahedron lies in $C_\ell\setminus(\partial C_\ell+B_{\delta'})$, where $\rho_\ell=\rho_0$. Hence the localized density equals $\rho_0\,\mathbb{1}_{Q^{-1}(h\mu_j\mathbb{\Delta}+h z+a)}*\eta_\delta$. Translation invariance, orthogonal invariance, and radiality of the smoothing function show that its energy is the same finite number $E(\rho_0\,\mathbb{1}_{h\mathbb{\Delta}}*\eta_\delta)$.

For $(z,j)\in J\setminus J_0$, the localized density $(\mathbb{1}_{Q^{-1}(h\mu_j\mathbb{\Delta}+h z+a)}*\eta_\delta)\rho_\ell$ vanishes outside $\partial C_\ell+B_{h'}$. Indeed, a point outside $C_\ell$ at which $\rho_\ell$ is nonzero is within distance $\delta'$ of its boundary. If instead $x\in C_\ell$ has distance at least $h'$ from the boundary and $(\mathbb{1}_{Q^{-1}(h\mu_j\mathbb{\Delta}+h z+a)}*\eta_\delta)(x)>0$, then $x$ lies in the $\delta$-enlargement of the tetrahedron. Every point of the tetrahedron is then within distance $d_0h+\delta$ of $x$, which would give $(z,j)\in J_0$. This proves the assertion.

The Lieb--Oxford inequality (Theorem~\ref{thm:basic_lieb_oxford}) and nonnegativity of the kinetic energy give $E(\rho)\geqslant-c_{\mathrm{LO}}\int_{\mathbb{R}^3}\rho^{4/3}$ for each of the localized densities $\rho$. For the sum over $J\setminus J_0$ we use that each smeared indicator is at most $1$, so that its $4/3$ power is at most the smeared indicator itself, together with the partition identity~\eqref{eq:basic_partition}. This avoids an estimate that grows with the overlap multiplicity or the number of boundary tetrahedra. We obtain
\begin{align*}
&\sum_{(z,j)\in J\setminus J_0}E\big((\mathbb{1}_{Q^{-1}(h\mu_j\mathbb{\Delta}+h z+a)}*\eta_\delta)\rho_\ell\big)\\
&\qquad\geqslant-c_{\mathrm{LO}}\int_{\partial C_\ell+B_{h'}}\rho_\ell^{4/3}
\sum_{(z,j)\in J\setminus J_0}(\mathbb{1}_{Q^{-1}(h\mu_j\mathbb{\Delta}+h z+a)}*\eta_\delta)^{4/3}\\
&\qquad\geqslant-c_{\mathrm{LO}}(\Lambda\rho_0)^{4/3}|\partial C_\ell+B_{h'}|
\geqslant-C(\Lambda\rho_0)^{4/3}\ell^2h'.
\end{align*}
For the interior contribution,~\eqref{eq:upper_interior_count} implies the sign-independent estimate
\[
|J_0|\,E(\rho_0\,\mathbb{1}_{h\mathbb{\Delta}}*\eta_\delta)
\geqslant\frac{\ell^3}{|h\mathbb{\Delta}|}E(\rho_0\,\mathbb{1}_{h\mathbb{\Delta}}*\eta_\delta)
-C\frac{|E(\rho_0\,\mathbb{1}_{h\mathbb{\Delta}}*\eta_\delta)|}{|h\mathbb{\Delta}|}\ell^2h'.
\]
Since the terms with $(z,j)\notin J$ vanish, combining the last two estimates, uniformly in $(Q,a)$, gives
\begin{multline}\label{eq:upper_local_sum_bound}
\sum_{z\in\mathbb{Z}^3}\sum_{j=1}^{24}E\big((\mathbb{1}_{Q^{-1}(h\mu_j\mathbb{\Delta}+h z+a)}*\eta_\delta)\rho_\ell\big)
\\
\geqslant \ell^3\frac{E(\rho_0\,\mathbb{1}_{h\mathbb{\Delta}}*\eta_\delta)}{|h\mathbb{\Delta}|}
-C \ell^2h'\left(\frac{|E(\rho_0\,\mathbb{1}_{h\mathbb{\Delta}}*\eta_\delta)|}{|h\mathbb{\Delta}|}+(\Lambda\rho_0)^{4/3}\right).
\end{multline}
This form is valid whether $E(\rho_0\,\mathbb{1}_{h\mathbb{\Delta}}*\eta_\delta)$ is positive, negative, or zero.

Insert~\eqref{eq:upper_local_sum_bound} and~\eqref{eq:upper_layer_integrals} into~\eqref{eq:upper_layer_localization}, noting that the normalized average of a uniform bound is the same bound and that $0<1-C\delta/h\leqslant1$. After dividing by $\ell^3$, we find
\begin{align*}
\frac{E(\rho_\ell)}{\ell^3}
&\geqslant\left(1-\frac{C\delta}h\right)\frac{E(\rho_0\,\mathbb{1}_{h\mathbb{\Delta}}*\eta_\delta)}{|h\mathbb{\Delta}|}\\
&\quad-C\frac{h'}{\ell}
\left(\frac{|E(\rho_0\,\mathbb{1}_{h\mathbb{\Delta}}*\eta_\delta)|}{|h\mathbb{\Delta}|}+(\Lambda\rho_0)^{4/3}\right)
-\frac{C(\Lambda\rho_0+\delta^3\Lambda^2\rho_0^2)}h
-\frac{C\Lambda\rho_0}{h\delta}.
\end{align*}
At fixed $h$, the energy $E(\rho_0\,\mathbb{1}_{h\mathbb{\Delta}}*\eta_\delta)$ is finite and $h'/\ell\to0$. Therefore
\[
\liminf_{\ell\to\infty}\frac{E(\rho_\ell)}{\ell^3}
\geqslant\left(1-\frac{C\delta}h\right)\frac{E(\rho_0\,\mathbb{1}_{h\mathbb{\Delta}}*\eta_\delta)}{|h\mathbb{\Delta}|}
-\frac{C_{\Lambda,\rho_0}}{h\delta}.
\]
 The hypotheses of Theorem~\ref{thm:UEG}(ii) hold as $h\to\infty$, since $\delta/h\to0$ and $\delta h\to\infty$. Thus
\[
\lim_{h\to\infty}\frac{E(\rho_0\,\mathbb{1}_{h\mathbb{\Delta}}*\eta_\delta)}{|h\mathbb{\Delta}|}=e_\mathrm{UEG}(\rho_0).
\]
Letting $h\to\infty$ at fixed $\delta$ in the previous lower bound proves~\eqref{eq:upper_bounded_layer}.

Uniformly for $a\in C_L$,
\begin{equation}\label{eq:upper_explicit_counting}
V(a,\ell)=\theta \ell^3+\mathcal O_{L,\delta}(\ell^2),
\qquad
A(a,\ell)\leqslant\frac3{r_*}V(a,\ell)\leqslant\frac3{r_*}\ell^3.
\end{equation}
